import Testing
@testable import DogearKit

@Test(arguments: [
    "org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType", "org.nspasteboard.AutoGeneratedType",
])
func aCopyWithOneMarkerIsIgnored(marker: String) {
    #expect(ClipboardPolicy.ignores([marker]))
}

@Test func aMarkerNextToOrdinaryTypesIsIgnored() {
    #expect(ClipboardPolicy.ignores(["public.utf8-plain-text", "org.nspasteboard.ConcealedType", "public.url"]))
}

@Test func ordinaryTypesAreNotIgnored() {
    #expect(!ClipboardPolicy.ignores(["public.utf8-plain-text", "public.url", "public.html"]))
}

@Test func anEmptyCopyIsNotIgnored() {
    #expect(!ClipboardPolicy.ignores([]))
}

@Test(arguments: ["org.nspasteboard.Concealed", "ConcealedType"])
func aNearMissIsNotIgnored(type: String) {
    #expect(!ClipboardPolicy.ignores([type]))
}
